<?php

$ref = static fn (string $sourceId, string $locator, string $status = 'belegt'): array => ['sourceId' => $sourceId, 'locatorType' => str_starts_with($sourceId, 'e') ? 'examTask' : 'document', 'locator' => $locator, 'sourceStatus' => $status];
$historical = 'Diese Darstellung folgt den bereitgestellten Lehrunterlagen und kann historisch oder vereinfacht sein.';

return [
    ['id' => 't1', 'slug' => 'grundlagen-und-schichten', 'areaId' => 'a1', 'title' => 'Kommunikationsmodelle und Referenzarchitekturen', 'intro' => 'Kommunikationssysteme verbinden Endsysteme über Protokolle, Dienste und geschichtete Teilaufgaben.', 'blocks' => [
        ['type' => 'comparison', 'title' => 'Rollenmodelle verteilter Kommunikation', 'content' => 'Beim Client/Server-Modell fordert ein Client Dienste eines Servers an. Ein Serververbund verteilt Aufgaben auf mehrere Server. Ein Forward-Proxy handelt für Clients, ein Reverse-Proxy steht vor Servern. Peer-to-Peer-Systeme verteilen Client- und Serverrollen auf Teilnehmer. Die Wahl verändert Zentralisierung, Lastverteilung und den Kommunikationsweg.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s01', 'Client/Server, Serververbund, Proxy und Peer-to-Peer')]],
        ['type' => 'comparison', 'title' => 'Kommunikationsarten und Netzklassen', 'content' => 'Synchrone Kommunikation koppelt die Beteiligten zeitlich, asynchrone entkoppelt sie. Unicast adressiert einen, Multicast eine Gruppe, Broadcast alle im Bereich und Anycast einen geeigneten Vertreter einer Gruppe. PAN, LAN, MAN und WAN ordnen Netze nach Ausdehnung; Punkt-zu-Punkt und Multi-Access nach gemeinsamer Mediennutzung.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s01', 'Kommunikationsarten und Netzklassifikation')]],
        ['type' => 'definition', 'title' => 'Protokoll, Dienst und Schnittstelle', 'content' => 'Ein Protokoll regelt die Kommunikation gleichrangiger Instanzen. Ein Dienst beschreibt, was eine Schicht der darüberliegenden Schicht anbietet; die Schnittstelle legt fest, wie dieser Dienst genutzt wird. Modularisierung trennt Aufgaben, damit Schichten unabhängig über definierte Schnittstellen zusammenarbeiten können.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s02', 'Protokolle, Dienste, Schnittstellen und Modularisierung')]],
        ['type' => 'comparison', 'title' => 'OSI und TCP/IP', 'content' => 'Das OSI-Modell gliedert Kommunikation in sieben Schichten. Die TCP/IP-Architektur fasst Aufgaben gröber zusammen. Beim Senden fügt jede Schicht Steuerinformationen hinzu; beim Empfangen werden sie schrittweise entfernt. Die entstehende Einheit heißt Protocol Data Unit.', 'items' => ['OSI: Anwendung, Darstellung, Sitzung, Transport, Vermittlung, Sicherung, Bitübertragung', 'TCP/IP: Anwendung, Transport, Internet, Netzzugang'], 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s02', 'Schichtenmodelle, Dienste und Kapselung')]],
        ['type' => 'definition', 'title' => 'Aufgaben der OSI-Schichten', 'content' => 'Anwendung stellt Anwendungsdienste bereit, Darstellung vereinbart Datenformate, Sitzung strukturiert Dialoge, Transport wirkt Ende zu Ende, Vermittlung adressiert und routet, Sicherung überträgt Rahmen über einen Link und Bitübertragung bildet Bits auf Signale ab. TCP/IP fasst Darstellung und Sitzung in der Anwendung sowie Sicherung und Bitübertragung im Netzzugang zusammen.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s02', 'OSI-Schichtfunktionen und TCP/IP-Zuordnung')]],
        ['type' => 'rule', 'title' => 'Graphmetriken', 'content' => 'Durchmesser, Bisektionsbreite und Knotengrad charakterisieren Netztopologien. Sie beschreiben maximale Weglänge, minimale Trennkapazität und Zahl direkter Nachbarn.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s01', 'Netztopologien und Graphmetriken'), $ref('e2016', 'Aufgabe 1')]],
    ], 'examNotes' => 'OSI-/TCP-IP-Zuordnungen und Topologiemetriken treten wiederholt in Prüfungsquellen auf.', 'relatedTopicIds' => ['t2', 't3'], 'clarityStatus' => 'unklar'],

    ['id' => 't2', 'slug' => 'sockets-und-datenformate', 'areaId' => 'a2', 'title' => 'Sockets und Datendarstellung', 'intro' => 'Verteilte Anwendungen benötigen Endpunkte und eine vereinbarte Darstellung übertragener Daten.', 'blocks' => [
        ['type' => 'definition', 'title' => 'Ports, Socket und ServerSocket', 'content' => 'Ein Port identifiziert einen Kommunikationsendpunkt innerhalb eines Rechners. Ein Socket verbindet Anwendungsprozess, Adresse, Port und Transportprotokoll. Der ServerSocket dient dem Lauschen und Annehmen neuer TCP-Verbindungen; für jede angenommene Verbindung entsteht ein eigener verbundener Socket.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s03', 'Ports, Socket und ServerSocket')]],
        ['type' => 'method', 'title' => 'TCP-Client/Server-Ablauf', 'content' => 'Voraussetzung sind Serveradresse und freier Dienstport. Der Server erzeugt einen ServerSocket, bindet ihn, lauscht und ruft accept auf. Der Client erzeugt einen Socket und verbindet sich. accept liefert serverseitig einen verbundenen Socket; danach lesen und schreiben beide Seiten und schließen ihre Verbindung. Das Ergebnis ist ein zuverlässiger Byte-Strom zwischen zwei Anwendungsendpunkten.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s03', 'Socket-Grundlagen und TCP-Ablauf')]],
        ['type' => 'rule', 'title' => 'Blockierende Operationen und Threads', 'content' => 'accept und Leseoperationen können warten, bis eine Verbindung beziehungsweise Daten eintreffen. Bearbeitet ein Server alles in einem Ablauf, blockiert eine wartende Verbindung weitere Clients. Ein Thread je Verbindung trennt das Warten und ermöglicht parallele Bedienung; die Folien verwenden Threads aus diesem Grund.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s03', 'Blockierende Socket-Operationen und Threads')]],
        ['type' => 'rule', 'title' => 'Codebeispiele richtig einordnen', 'content' => 'Die Socket-Codebeispiele veranschaulichen den Ablauf von bind, listen, accept, connect, Lesen, Schreiben und close. Sie sind Ablaufquellen für das Verständnis, aber keine verpflichtenden Programmieraufgaben und ersetzen nicht die fachlichen Erklärungen der Lerninhalte.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s03', 'Socket-Abläufe')]],
        ['type' => 'method', 'title' => 'Marshalling mit ASN.1 und BER', 'content' => 'Voraussetzung ist eine gemeinsame Beschreibung der übertragenen Struktur. ASN.1 beschreibt die Typen unabhängig von einer Programmiersprache. BER kodiert Werte nach dieser Beschreibung in eine übertragbare Bytefolge. Die Gegenseite dekodiert die Folge und rekonstruiert die Werte. Little- und Big-Endian betreffen dabei die Reihenfolge mehrbyteiger Darstellungen.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s04', 'Byte-Reihenfolge, Marshalling, ASN.1 und BER')]],
        ['type' => 'method', 'title' => 'Objektserialisierung', 'content' => 'Serialisierung überführt den Zustand eines Objekts in eine speicher- oder übertragbare Folge; Deserialisierung stellt daraus wieder ein Objekt her. Sender und Empfänger benötigen kompatible Klassen- und Formatannahmen. Die Folien zeigen Java-Objektserialisierung als konkreten Mechanismus.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s04', 'Java-Objektserialisierung und Deserialisierung')]],
        ['type' => 'comparison', 'title' => 'XML-Schema und JSON', 'content' => 'XML muss zunächst wohlgeformt sein und kann zusätzlich gegen XSD validiert werden. XSD sequence verlangt Reihenfolge, choice eine Alternative und all eine ungeordnete Menge erlaubter Elemente. Namespaces trennen Vokabulare. JSON bildet Werte, Objekte und Arrays kompakter ab; die Formate unterscheiden sich damit in Auszeichnung, Strukturprüfung und Umfang.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s04', 'XML, Namespaces, XSD-Kompositoren und JSON')]],
    ], 'examNotes' => 'Programmcode in den Folien erklärt Abläufe, ist hier aber keine Programmieraufgabe.', 'relatedTopicIds' => ['t1', 't5'], 'clarityStatus' => 'belegt'],

    ['id' => 't3', 'slug' => 'adressierung-und-routing', 'areaId' => 'a3', 'title' => 'Adressierung, Vermittlung und Routing', 'intro' => 'IP adressiert Schnittstellen und vermittelt Pakete über Subnetze und autonome Systeme.', 'blocks' => [
        ['type' => 'definition', 'title' => 'Internet, autonome Systeme und IPv4', 'content' => 'Das Internet verbindet Netze und autonome Systeme. IPv4-Adressen gliedern sich in Netz- und Hostanteil; historische Klassen, private Bereiche und Loopback-Adressen ordnen besondere Verwendungsfälle ein. Ein Endsystem vergleicht sein eigenes Präfix mit dem Zielpräfix, um zwischen direkter Zustellung im Subnetz und Weitergabe an einen Router zu entscheiden.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s05', 'Internet, autonome Systeme, IPv4 und historische Adressklassen')]],
        ['type' => 'method', 'title' => 'Subnetz und Adressbereich bestimmen', 'content' => 'Voraussetzung sind IPv4-Adresse und Präfix beziehungsweise Maske. 1. Maske aus der Präfixlänge bilden. 2. Adresse bitweise mit der Maske UND-verknüpfen; das Ergebnis ist die Netzadresse. 3. Hostbits nur 0 ergeben die Netzadresse, Hostbits nur 1 die Broadcastadresse. 4. Die dazwischenliegenden Adressen bilden den in den Aufgaben verwendeten Hostbereich. Ergebnis sind Netz, Broadcast und Zahl der nutzbaren Hosts.', 'formula' => 'Netzadresse = IPv4-Adresse AND Subnetzmaske; Hosts = 2^h − 2', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s05', 'IPv4, Subnetting und Auswahl einer Subnetzmaske'), $ref('e2016', 'Aufgabe 2')]],
        ['type' => 'method', 'title' => 'CIDR-Routen aggregieren', 'content' => 'Voraussetzung sind benachbarte Präfixe mit demselben Next Hop. 1. Gemeinsame führende Bits bestimmen. 2. Daraus das kürzere Sammelpräfix bilden. 3. Prüfen, ob das Präfix unbeabsichtigte Zwischenbereiche umfasst. 4. Solche Ausnahmen bei Bedarf durch längere, spezifischere Präfixe korrigieren. Ergebnis ist eine kleinere Routingtabelle ohne Änderung der beabsichtigten Weiterleitung.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s06', 'CIDR, Delegation und Routenaggregation')]],
        ['type' => 'method', 'title' => 'Longest Prefix Match', 'content' => 'Alle passenden Routingeinträge werden betrachtet; der Eintrag mit dem längsten Präfix gewinnt. Die Default-Route 0.0.0.0/0 greift nur, wenn kein spezifischerer Eintrag passt.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s06', 'Routingtabellen und Longest Prefix Match'), $ref('e2016', 'Aufgabe 2')]],
        ['type' => 'method', 'title' => 'Link State und Dijkstra', 'content' => 'Voraussetzung ist die durch Topologieinformationen bekannte Netzstruktur mit Verbindungskosten. 1. Jeder Router verteilt seine lokalen Verbindungen. 2. Alle Router bauen daraus dieselbe Topologiesicht auf. 3. Dijkstra übernimmt schrittweise den noch nicht festgelegten Knoten mit kleinster vorläufiger Distanz. 4. Die Kosten seiner Nachbarn werden über diesen Knoten aktualisiert. Ergebnis ist ein Baum kürzester Wege und daraus die Weiterleitungstabelle.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s08', 'Control Plane, Link State und Dijkstra')]],
        ['type' => 'method', 'title' => 'Distance Vector', 'content' => 'Jeder Router startet mit den bekannten Kosten zu direkten Nachbarn. Er tauscht seine Distanztabelle mit Nachbarn aus, addiert die Kosten zum jeweiligen Nachbarn und übernimmt günstigere Wege. Wiederholter Austausch führt zu angepassten Distanz- und Next-Hop-Einträgen. Im Unterschied zu Link State kennt ein Router dabei nicht zwingend die vollständige Topologie.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s08', 'Distance Vector und Protokollvergleich')]],
        ['type' => 'comparison', 'title' => 'Routingprotokolle', 'content' => 'RIP gehört zum Distance-Vector-Umfeld; OSPF und IS-IS zu Link State. Diese Protokolle arbeiten innerhalb autonomer Systeme. BGP verbindet autonome Systeme und ist damit dem Inter-AS-Routing zugeordnet.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s08', 'Intra-/Inter-AS, RIP, OSPF, IS-IS und BGP')]],
        ['type' => 'method', 'title' => 'NAT- und NAPT-Übersetzung', 'content' => 'Beim ausgehenden Paket ersetzt das NAT-Gerät die interne Adresse; NAPT ordnet zusätzlich den internen Port einem externen Port zu und speichert diese Zuordnung. Beim Antwortpaket schlägt es die Zuordnung nach und stellt interne Adresse und Port wieder her. Die Zuordnung beeinflusst eingehende Erreichbarkeit; die Folien unterscheiden Full Cone, Restricted Cone, Port Restricted Cone und Symmetric NAT und behandeln daraus entstehende Traversal-Probleme.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s07', 'NAT-/NAPT-Tabelle, NAT-Typen und Traversal')]],
        ['type' => 'method', 'title' => 'ARP und DHCP', 'content' => 'ARP sendet für eine gesuchte IPv4-Adresse eine Anfrage im lokalen Netz; der zuständige Teilnehmer antwortet mit seiner MAC-Adresse, die anschließend für den lokalen Rahmen verwendet werden kann. DHCP liefert einem Client Konfigurationsdaten wie die IP-Konfiguration. RARP wird in den Unterlagen als verwandter historischer Mechanismus eingeordnet.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s09', 'ARP Request/Reply, RARP und DHCP')]],
        ['type' => 'method', 'title' => 'IP-Fragmentierung durchführen', 'content' => 'Voraussetzung sind Paketlänge, IP-Headerlänge und MTU des nächsten Netzes. 1. Maximale Nutzdaten pro Fragment als MTU minus Header bestimmen. 2. Für alle Nicht-Endfragmente auf ein durch acht teilbares Nutzdatenvielfaches abrunden. 3. Nutzdaten aufteilen. 4. Total Length aus jeweiliger Nutzlast plus Header bilden. 5. Fragment Offset als bisher übertragene Nutzdaten geteilt durch acht eintragen. Der Offset zählt damit 8-Byte-Einheiten, nicht einzelne Bytes. More Fragments wird außer beim letzten Fragment gesetzt. Die Wiederzusammensetzung erfolgt am Ziel.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s09', 'IPv4-Header, MTU und Fragmentierung'), $ref('e2016', 'Aufgabe 2')]],
        ['type' => 'comparison', 'title' => 'ARP-Schichtzuordnung', 'content' => 'Die Unterlagen dokumentieren drei Perspektiven: Schicht 2 nach üblicher Literaturzuordnung, Schicht 3 aus Sicht der Betriebssystemerzeugung in der Internetarchitektur und Schicht 2.5 als Zwischenposition. Eine absolute Einzelzuordnung wäre daher irreführend.', 'items' => ['Schicht 2: Zuordnung in der Literatur', 'Schicht 3: Erzeugung durch die Internet-Schicht', 'Schicht 2.5: vermittelnde Zwischenposition'], 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s09', 'ARP und Schichtzuordnung')]],
    ], 'examNotes' => 'CIDR, Routingtabellen und Fragmentierung gehören zu den häufigsten Rechen- und Begründungsaufgaben.', 'relatedTopicIds' => ['t1', 't4'], 'clarityStatus' => 'mehrdeutig'],

    ['id' => 't4', 'slug' => 'zuverlaessigkeit-und-tcp', 'areaId' => 'a4', 'title' => 'Zuverlässigkeit und TCP', 'intro' => 'Zuverlässiger Transport kombiniert Rückmeldungen, Sequenznummern, Timer und Fenstersteuerung.', 'blocks' => [
        ['type' => 'method', 'title' => 'Stop-and-Wait und ARQ', 'content' => 'Der Sender versieht Daten mit einer Sequenznummer, sendet genau eine Einheit und startet einen Timer. Bei passendem ACK fährt er mit der nächsten Sequenznummer fort. Gehen Daten verloren, löst der Timer eine Wiederholung aus. Geht das ACK verloren, trifft die Wiederholung als Duplikat ein; der Empfänger erkennt sie an der Sequenznummer, verwirft die Nutzdaten und bestätigt erneut. Ergebnis ist zuverlässige Übertragung mit höchstens einer ausstehenden Einheit.', 'formula' => 'Nutzungsgrad ρ = (L/R) / (L/R + RTT)', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s10', 'Send and Wait, verlorene Daten, verlorenes ACK und Sequenznummern')]],
        ['type' => 'formula', 'title' => 'Stop-and-Wait auswerten', 'content' => 'Zuerst die Sendedauer L/R aus Rahmenlänge L und Datenrate R bestimmen. Dann durch Sendedauer plus RTT teilen. Ein kleiner Wert zeigt, dass die Leitung während des Wartens ungenutzt bleibt. Pipelining erhöht die Zahl gleichzeitig ausstehender Einheiten und kann die Auslastung höchstens bis 1 steigern.', 'formula' => 'ρ = (L/R) / (L/R + RTT)', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s10', 'Nutzungsgrad und Übergang zum Pipelining')]],
        ['type' => 'comparison', 'title' => 'Go-Back-N, Selective Repeat und Selective Reject', 'content' => 'Go-Back-N akzeptiert am Empfänger nur die erwartete Reihenfolge und wiederholt nach Timeout den fehlenden sowie alle später gesendeten Rahmen. Selective Repeat puffert korrekt eingetroffene spätere Rahmen und wiederholt gezielt fehlende. Selective Reject fordert einen bestimmten fehlenden Rahmen gezielt an. Kumulative ACKs bestätigen einen zusammenhängenden Präfix; Duplicate ACKs zeigen wiederholt dieselbe Lücke.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s11', 'GBN, Selective Repeat/Reject, Pufferung und ACK-Verhalten')]],
        ['type' => 'formula', 'title' => 'Fenster, Durchsatz und Bandwidth-Delay-Produkt', 'content' => 'Ein Fenster w begrenzt die Datenmenge pro RTT. Um eine Leitung auszulasten, muss das Fenster mindestens das Bandwidth-Delay-Produkt aufnehmen. Einheiten müssen konsistent sein.', 'formula' => 'Durchsatz ≤ w / RTT; w ≥ Bandbreite · RTT', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s11', 'Durchsatz und Bandwidth-Delay-Produkt'), $ref('e2016', 'Aufgabe 3')]],
        ['type' => 'method', 'title' => 'TCP-Fluss- und Staukontrolle', 'content' => 'Der Empfänger meldet im Receiver Window freien Puffer; der Sender hält seine ausstehenden Daten darunter. Zusätzlich begrenzt das Congestion Window die Netzbelastung. Slow Start vergrößert das Staufenster anfangs stark, Congestion Avoidance anschließend vorsichtiger. Mehrere Duplicate ACKs können eine vermutete Lücke per Fast Retransmit vor dem Timeout erneut senden; Fast Recovery passt danach das Fenster an.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s12', 'Receiver Window, Slow Start, Congestion Avoidance, Fast Retransmit und Recovery')]],
        ['type' => 'method', 'title' => 'RTT und Timeout nachführen', 'content' => 'TCP misst die Zeit zwischen Senden und passender Bestätigung. Die Unterlagen bilden aus Messungen eine geglättete RTT-Schätzung und berücksichtigen die Abweichung für den Timeout. Der Timeout muss auf wechselnde Laufzeiten reagieren: zu klein erzeugt unnötige Wiederholungen, zu groß verzögert die Fehlerreaktion.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s12', 'RTT-Schätzung und Retransmission Timeout')]],
        ['type' => 'method', 'title' => 'TCP-Verbindung auf- und abbauen', 'content' => 'Beim Aufbau synchronisieren Client und Server ihre Sequenzräume mit SYN, SYN+ACK und ACK. Danach ist die Verbindung in beiden Richtungen nutzbar. Beim regulären Abbau werden die beiden Richtungen mit FIN und ACK getrennt geschlossen, weshalb der Ablauf vier Segmente umfassen kann. Die Zustände verhindern, dass alte Segmente unmittelbar einer neuen Verbindung zugerechnet werden.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s12', 'Drei-Wege-Handshake, Verbindungsabbau und Zustände')]],
        ['type' => 'definition', 'title' => 'TCP-Header und Zusatzmechanismen', 'content' => 'Ports identifizieren Anwendungen, Sequenz- und ACK-Nummer ordnen den Byte-Strom, Flags steuern Aufbau und Abbau, das Fenster meldet Empfangskapazität. Delayed ACK wartet kurz auf eine gemeinsame Bestätigung, Piggybacking verbindet ACK und Rückdaten, Nagle bündelt kleine Sendungen; Push und Urgent Pointer markieren besondere Behandlung im in den Unterlagen dargestellten Modell.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s12', 'TCP-Header, Delayed ACK, Piggybacking, Nagle, Push und Urgent Pointer')]],
    ], 'examNotes' => 'Fehlerabläufe, Fenstergrößen und TCP-Durchsatz werden wiederholt geprüft.', 'relatedTopicIds' => ['t3', 't5', 't7'], 'clarityStatus' => 'unklar'],

    ['id' => 't5', 'slug' => 'udp-dns-und-anwendungsprotokolle', 'areaId' => 'a5', 'title' => 'UDP, DNS und Anwendungsprotokolle', 'intro' => 'Anwendungsprotokolle nutzen unterschiedliche Transport- und Darstellungsmechanismen.', 'blocks' => [
        ['type' => 'definition', 'title' => 'UDP-Header und Checksumme', 'content' => 'UDP ist verbindungslos. Sein Header enthält Quell- und Zielport, Länge und Checksumme. Zur Prüfsumme werden die in den Unterlagen vorgesehenen Wörter einschließlich zusätzlicher IP-bezogener Angaben einbezogen; der Empfänger berechnet erneut und erkennt eine Abweichung, ohne dass UDP selbst Wiederholung oder Reihenfolge garantiert.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s13', 'UDP-Header und Checksumme')]],
        ['type' => 'method', 'title' => 'Medien digitalisieren und Bitrate bestimmen', 'content' => 'Ein analoges Signal wird abgetastet, jeder Messwert quantisiert und anschließend binär kodiert. Die Abtastrate muss laut Nyquist mindestens doppelt so groß wie die höchste Signalfrequenz sein. Abtastrate, Bits je Wert und Kanalzahl ergeben die unkomprimierte Bitrate. Ergebnis ist ein digitaler Datenstrom für Speicherung oder Übertragung.', 'formula' => 'Abtastfrequenz ≥ 2 · maximale Signalfrequenz; Bitrate = Abtastrate · Bits je Wert · Kanäle', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s13', 'Abtastung, Quantisierung, Kodierung und Bitrate')]],
        ['type' => 'method', 'title' => 'Streaming und Wiedergabepuffer', 'content' => 'Pakete treffen wegen Laufzeitschwankungen nicht gleichmäßig ein. Ein Playback-Puffer sammelt zunächst Daten und startet die Wiedergabe verzögert. Danach entnimmt die Anwendung mit gleichmäßiger Rate. Ein größerer Puffer toleriert mehr Jitter, erhöht aber die Verzögerung. RTP transportiert Mediendaten, RTCP liefert Kontrollinformationen und RTSP steuert Sitzungen; HLS und DASH segmentieren adaptive Übertragung.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s13', 'Streaming, Jitter, Playback-Puffer und Medienprotokolle')]],
        ['type' => 'definition', 'title' => 'DNS-Namensraum, Domäne und Zone', 'content' => 'Der hierarchische Namensraum besteht aus Labels; ein vollständiger Name ist ein FQDN. Eine Domäne bezeichnet einen Teilbaum des Namensraums. Eine Zone ist der administrativ von einem Nameserver verantwortete Teil und kann Unterdomänen delegieren. Resource Records speichern unter anderem Zuordnungen und Verweise.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s14', 'Labels, FQDN, Domänen, Zonen, Delegation und Records')]],
        ['type' => 'method', 'title' => 'DNS-Auflösung', 'content' => 'Der Resolver fragt einen Nameserver. Bei rekursiver Auflösung übernimmt dieser die weiteren Schritte und liefert das Endergebnis. Bei iterativer Auflösung erhält der Anfragende Verweise und folgt ihnen von der Hierarchie zur zuständigen Zone. Resource Records liefern die Antwort; Caching spart weitere Anfragen, kann aber veraltete oder manipulierte Einträge weitertragen. Die Folien behandeln dazugehörige Angriffe.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s14', 'Rekursive/iterative Auflösung, Records, Caching und Angriffe')]],
        ['type' => 'comparison', 'title' => 'Aktives und passives FTP', 'content' => 'FTP trennt Steuer- und Datenverbindung. Beim aktiven FTP baut der Server die Datenverbindung zum Client auf; beim passiven FTP teilt der Server einen erreichbaren Port mit und der Client baut auch die Datenverbindung auf. Die Rollen beim Datenverbindungsaufbau sind der entscheidende Unterschied.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s15', 'FTP: Steuerverbindung, aktiver und passiver Modus')]],
        ['type' => 'comparison', 'title' => 'E-Mail-Protokolle und MIME', 'content' => 'SMTP transportiert Nachrichten zum Server und zwischen Servern. POP3 und IMAP dienen dem Abruf; IMAP unterstützt die serverseitige Verwaltung stärker. MIME erweitert das Nachrichtenformat um unterschiedliche Inhaltstypen und Anhänge.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s15', 'SMTP, POP3, IMAP und MIME')]],
    ], 'examNotes' => 'TLS und Serialisierung erscheinen im Gedächtnisprotokoll 2018 nur als Relevanzhinweis.', 'relatedTopicIds' => ['t2', 't4'], 'clarityStatus' => 'unklar'],

    ['id' => 't6', 'slug' => 'lan-und-ethernet', 'areaId' => 'a6', 'title' => 'LAN, Medienzugriff und Ethernet', 'intro' => 'Die Sicherungsschicht rahmt Daten und regelt den gemeinsamen Zugriff auf ein Medium.', 'blocks' => [
        ['type' => 'definition', 'title' => 'Framing, Medien und Netzkomponenten', 'content' => 'LLC und MAC teilen Aufgaben der Sicherungsschicht. Bus, Ring und Stern beschreiben Topologien. Repeater regeneriert Signale, ein Hub verteilt sie an alle Ports. Bridge und Switch filtern Rahmen anhand gelernter MAC-Adressen; ein Router vermittelt Pakete zwischen Netzen. Kupfer und Glasfaser unterscheiden sich in Übertragungsmedium und den in den Folien verglichenen Reichweiten- und Störeigenschaften.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s16', 'Sicherungsschicht, Topologien, Komponenten und Übertragungsmedien')]],
        ['type' => 'method', 'title' => 'Switch-Learning und Broadcast', 'content' => 'Bei jedem eingehenden Rahmen merkt sich der Switch die Quell-MAC-Adresse zusammen mit dem Eingangsport. Ist die Zieladresse bekannt, leitet er nur zum zugehörigen Port weiter; ist sie unbekannt oder ein Broadcast, verteilt er den Rahmen an die übrigen Ports. Gelernte Einträge ermöglichen anschließend gezielte Weiterleitung.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s16', 'Bridge, Switch-Learning und Broadcast-Verhalten')]],
        ['type' => 'method', 'title' => 'CSMA/CD und Binary Exponential Backoff', 'content' => 'Eine Station hört das Medium und sendet bei Freiheit. Während des Sendens überwacht sie Kollisionen. Nach einer Kollision bricht sie ab; Binary Exponential Backoff wählt zufällig einen Wartewert aus einem mit den Versuchen wachsenden Bereich. Danach prüft die Station erneut. Das Ergebnis ist eine dezentrale Wiederholungsregel, deren Wartebereich bei anhaltender Last wächst.', 'formula' => 'Sendedauer ≥ 2 · maximale Signallaufzeit', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s17', 'CSMA/CD und Binary Exponential Backoff')]],
        ['type' => 'definition', 'title' => 'Ethernet-Rahmen und Varianten', 'content' => 'Der Ethernet-Rahmen enthält Präambel/Startbegrenzung, Ziel- und Quelladresse, Längen-/Typfeld, Nutzdaten mit gegebenenfalls Padding und FCS. Fast und Gigabit Ethernet erhöhen die Rate und müssen die Bedingungen des jeweiligen Medienzugriffs berücksichtigen; die Probeklausur fragt besonders, wie Fast Ethernet trotz höherer Rate die Kollisionsbedingung behandelt.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s17', 'Ethernet-Rahmen, Fast Ethernet und Gigabit Ethernet'), $ref('e2016', 'Aufgabe 5')]],
        ['type' => 'formula', 'title' => 'Ethernet-Mindestrahmen', 'content' => 'Für das belegte 10-Mbit/s-Beispiel ergibt die Round-Trip-Laufzeit 51,2 µs eine Mindestlänge von 512 Bit beziehungsweise 64 Byte.', 'formula' => '10 Mbit/s · 51,2 µs = 512 Bit = 64 Byte', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s17', 'Ethernet-Mindestrahmen'), $ref('e2016', 'Aufgabe 5')]],
        ['type' => 'comparison', 'title' => 'Kanalzuteilung und ALOHA', 'content' => 'TDMA und FDMA teilen Zeit beziehungsweise Frequenz fest auf. ALOHA lässt Stationen konkurrierend senden und reagiert auf Konflikte; CSMA hört zuvor das Medium. Die Verfahren unterscheiden feste Zuteilung von dynamischem Wettbewerb und damit Auslastung und Kollisionsrisiko.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s17', 'TDMA, FDMA, ALOHA und CSMA-Taxonomie')]],
        ['type' => 'method', 'title' => 'Token Ring', 'content' => 'Ein Token umläuft den Ring. Nur die Station mit Token darf senden und gibt es anschließend weiter. Dadurch werden Kollisionen vermieden und der Zugriff geordnet. Gegenüber konkurrierendem CSMA entsteht vorhersagbarerer und fairer Zugriff, aber der Token und die Ringorganisation erzeugen zusätzlichen Ablaufaufwand.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s17', 'Token Ring und Vergleich zum konkurrierenden Zugriff')]],
    ], 'examNotes' => 'Ethernet-Mindestlänge, Fast Ethernet und Bridge-Verhalten sind wiederkehrende Prüfungsthemen.', 'relatedTopicIds' => ['t7', 't8'], 'clarityStatus' => 'mehrdeutig'],

    ['id' => 't7', 'slug' => 'hamming-und-crc', 'areaId' => 'a7', 'title' => 'Hamming-Abstand und CRC', 'intro' => 'Redundanz ermöglicht, Übertragungsfehler zu erkennen oder zu korrigieren.', 'blocks' => [
        ['type' => 'formula', 'title' => 'Hamming-Abstand', 'content' => 'Der Hamming-Abstand zählt verschiedene Bitpositionen. Um e Bitfehler sicher zu erkennen, ist Mindestabstand e+1 nötig; zur Korrektur e Fehler Mindestabstand 2e+1.', 'formula' => 'd_min ≥ e + 1 (Erkennung); d_min ≥ 2e + 1 (Korrektur)', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s18', 'Hamming-Abstand und Fehlerfähigkeit')]],
        ['type' => 'comparison', 'title' => 'Parität, FEC und ARQ', 'content' => 'Ein Paritätsbit liefert einfache Redundanz. Forward Error Correction ermöglicht Korrektur ohne Rückfrage; ARQ fordert bei erkannten Fehlern eine Wiederholung an.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s18', 'Parität, FEC und ARQ')]],
        ['type' => 'method', 'title' => 'CRC-Verfahren', 'content' => 'Die Daten D werden um r Nullbits erweitert und modulo 2 durch das Generatorpolynom G dividiert. Der Rest R wird angehängt. Der Empfänger dividiert erneut; Rest 0 bedeutet, dass das geprüfte Codewort die CRC-Prüfung besteht.', 'formula' => 'R = Rest von (D · 2^r) / G in Modulo-2-Arithmetik', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s18', 'CRC und Polynomcodes'), $ref('e2016', 'Aufgabe 5')]],
        ['type' => 'method', 'title' => 'CRC schriftlich anwenden', 'content' => 'Generatorgrad r bestimmen und r Nullbits an D anhängen. Die führende 1 des aktuellen Dividendenrests mit der führenden 1 von G ausrichten und die Bits per XOR subtrahieren; bis zum Ende wiederholen. Den r Bit langen Rest an die ursprünglichen Daten hängen. Zur Kontrolle das Codewort erneut durch G teilen; Rest 0 besteht die Prüfung.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s18', 'Durchgerechnetes CRC-Beispiel und Lösung'), $ref('e2016', 'Aufgabe 5d')]],
    ], 'examNotes' => 'CRC-Rechnungen und Hamming-Abstände sind prüfungsrelevant.', 'relatedTopicIds' => ['t4', 't6'], 'clarityStatus' => 'unklar'],

    ['id' => 't8', 'slug' => 'leitungscodes-modulation-wlan', 'areaId' => 'a8', 'title' => 'Leitungscodes, Modulation und WLAN', 'intro' => 'Bits werden als Leitungssignale oder modulierte Träger übertragen; Funknetze benötigen besondere Zugriffsregeln.', 'blocks' => [
        ['type' => 'comparison', 'title' => 'Basisband, Breitband und Anforderungen', 'content' => 'Basisband überträgt das codierte Signal direkt im verfügbaren Band; Breitband legt Information auf Trägerbereiche. Leitungscodes werden in den Unterlagen unter anderem nach Gleichanteil, Taktrückgewinnung, Bandbreitenbedarf und eindeutiger Dekodierbarkeit beurteilt.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s19', 'Basis-/Breitband und Anforderungen an Leitungscodes')]],
        ['type' => 'method', 'title' => 'Leitungscodes zeichnen und vergleichen', 'content' => 'Zuerst Bitgrenzen und einen konsistenten Startpegel markieren. Für jedes Bit die jeweilige Regel anwenden: NRZ arbeitet mit Pegeln, NRZI mit Übergang oder Nichtübergang, RZ kehrt innerhalb des Bits zurück, Manchester besitzt einen Übergang in der Bitmitte und Differential Manchester wertet Übergänge relativ aus. Danach Signalwechsel, Gleichanteil und Taktrückgewinnung vergleichen.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s19', 'NRZ, NRZI, RZ, Manchester und Differential Manchester')]],
        ['type' => 'method', 'title' => 'Blockcodes anwenden', 'content' => 'Bei 4B/5B wird jede Vier-Bit-Gruppe über die in den Unterlagen gegebene Tabelle auf fünf Codebits abgebildet; daraus folgt 80 Prozent Nutzbitanteil. 8B/10B bildet acht Datenbits auf zehn Codebits ab und verfolgt zusätzliche Signaleigenschaften. Für konkrete Kodierungen ist die jeweilige Quelltabelle maßgeblich.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s19', '4B/5B- und 8B/10B-Codierungstabellen')]],
        ['type' => 'comparison', 'title' => 'Modulationsverfahren auswählen', 'content' => 'ASK ordnet Symbolen Amplituden, FSK Frequenzen und PSK Phasen zu. BPSK verwendet zwei, QPSK vier Phasenlagen und trägt laut lesbarem Spezialfall zwei Bit je Symbol. QAM kombiniert Amplitude und Phase für mehr Signalpunkte. Zur Auswahl werden benötigte Symbolzahl, Robustheit und die in den Unterlagen gezeigten Signalräume verglichen.', 'formula' => 's(t) = A · sin(2πft + φ)', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s19', 'ASK, FSK, BPSK, QPSK und QAM')]],
        ['type' => 'formula', 'title' => 'Kanaleigenschaften', 'content' => 'Die freie Empfangsleistung fällt in den Unterlagen proportional zu 1/d^a. Die Shannon-Grenze verbindet Bandbreite und Signal-Rausch-Verhältnis.', 'formula' => 'C = B · log₂(1 + SNR)', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s19', 'Ausbreitung, SNR und Shannon')]],
        ['type' => 'method', 'title' => 'CSMA/CA im WLAN', 'content' => 'WLAN arbeitet in Infrastruktur- oder Ad-hoc-Netzen und nutzt Kanäle sowie MIMO. Wegen Hidden und Exposed Stations wird Kollisionserkennung durch Vermeidung ersetzt: Nach freiem Medium und IFS zählt die Station einen zufälligen Backoff herunter, sendet und erwartet ein ACK. Optional reservieren RTS und CTS das Medium vor den Nutzdaten.', 'sourceStatus' => 'belegt', 'sourceRefs' => [$ref('s19', 'WLAN, CSMA/CA, ACK und RTS/CTS')]],
    ], 'examNotes' => 'Leitungscodes, QAM sowie der Unterschied zwischen CSMA/CD und CSMA/CA werden häufig geprüft.', 'relatedTopicIds' => ['t6', 't7'], 'clarityStatus' => 'unklar'],
];